#!/usr/bin/env bash
# The lock names a SIGNED SEB release, and nothing edits it by hand (estate/lib/seb-upgrade-sign.sh,
# estate/seb-upgrade.sh --verify). The same gate in every estate (SEB's tools/estate/scaffold/).
#
# Part A, the real tree, offline: every Application estate/seb-upgrade.sh generated (in any
#   environment's apps-dir, estate/seb-upgrade.conf) deploys the locked digest, names it in spec.info
#   where it names one, and platform-lock.yaml carries the lock verbatim. Planted on a copy: the lock's
#   digest edited by hand → [lock-edited]; the lock's version edited by hand → [lock-edited].
#   A lock that names no digest yet (the estate has taken no bundle) with no generated Application holds.
# Part B, against an in-memory registry on loopback (lib/oci-registry.mjs), a throwaway key pair
#   pinned as the trust anchor, and signed_release itself:
#   B1 a bundle signed for v1.2.3 at the tag's commit holds
#   B2 a digest typed by hand (an unsigned bundle)            → refused
#   B3 the signed bundle named as another version (v1.2.4)    → refused
#   B4 the signed bundle with another tag commit              → refused
#   B5 a bundle signed by another key                         → refused
#   and the pinned trust anchor estate/seb-cosign.pub is a PEM public key.
#
#   .github/scripts/tests/seb-lock-signed_test.sh
set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/lib/gate.sh"

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
cd "$root"
fails=0
ok() { echo "  ok   $1"; }
bad() { echo "  FAIL $1"; fails=$((fails + 1)); }
work="$(mktemp -d)"; gate_on_exit "rm -rf '$work'"
[ -r estate/seb-upgrade.conf ] || gate_abort "no estate/seb-upgrade.conf: this estate's upgrade settings are not declared"
apps_glob="$(sed -n 's/^apps-dir[[:space:]]*=[[:space:]]*//p' estate/seb-upgrade.conf)"
[ -n "$apps_glob" ] || gate_abort "estate/seb-upgrade.conf names no apps-dir"
apps_glob="${apps_glob//\{env\}/*}"

# ── Part A ──
consistent() { # <repo root> → prints one FAIL line per inconsistency, exit 1 on any
  local r="$1" digest version n=0 f got
  digest="$(sed -n 's/^digest = //p' "$r/estate/platform.lock")"
  version="$(sed -n 's/^version = //p' "$r/estate/platform.lock")"
  for f in "$r"/$apps_glob/*.yaml; do
    [ -e "$f" ] || continue
    grep -q '^# GENERATED by estate/seb-upgrade.sh' "$f" || continue
    got="$(sed -n 's/^    targetRevision: \(sha256:[0-9a-f]*\)$/\1/p' "$f")"
    [ -z "$got" ] || [ "$got" = "$digest" ] || { echo "  FAIL [lock-edited] ${f#"$r"/} deploys $got, the lock names ${digest:-no digest}"; n=$((n + 1)); }
    if grep -q 'name: seb-bundle$' "$f"; then
      [ -n "$digest" ] && grep -q "value: .*/seb/bundle@$digest\$" "$f" || { echo "  FAIL [lock-edited] ${f#"$r"/} names another bundle in spec.info than the lock's ${digest:-(none)}"; n=$((n + 1)); }
    fi
    grep -q "from the locked bundle $version\." "$f" || [ -z "$got" ] || { echo "  FAIL [lock-edited] ${f#"$r"/} was generated from another version than the lock's $version"; n=$((n + 1)); }
  done
  for f in "$r"/$apps_glob/platform-lock.yaml; do
    [ -e "$f" ] || continue
    diff -q <(sed -n 's/^    //p' "$f" | grep -E '^(version|digest|source) = ') <(grep -E '^(version|digest|source) = ' "$r/estate/platform.lock") >/dev/null \
      || { echo "  FAIL [lock-edited] ${f#"$r"/} does not carry the lock verbatim"; n=$((n + 1)); }
  done
  [ "$n" = 0 ]
}
generated() { local f; for f in "$root"/$apps_glob/*.yaml; do [ -e "$f" ] && grep -q '^# GENERATED by estate/seb-upgrade.sh' "$f" && echo "$f"; done; }
digest="$(sed -n 's/^digest = //p' estate/platform.lock)"
if out="$(consistent "$root")"; then
  if [ -z "$digest" ] && [ -z "$(generated)" ]; then ok "A the lock names no digest yet and nothing is generated from one: this estate has taken no bundle"
  else ok "A the real lock and every generated Application agree ($(sed -n 's/^version = //p' estate/platform.lock) @ ${digest:0:19}…)"; fi
else bad "A the real tree: $out"; fi
# The plants: a copy of every apps-dir and the lock, edited.
plant_copy() { # <dir>
  local d
  mkdir -p "$1/estate"; cp estate/platform.lock "$1/estate/"
  for d in "$root"/$apps_glob; do [ -d "$d" ] || continue; mkdir -p "$1/${d#"$root"/}"; cp -r "$d"/. "$1/${d#"$root"/}/"; done
}
if [ -z "$(generated)" ]; then echo "  n/a  A1 A2 nothing is generated from the lock to disagree with it"
else
  plant_copy "$work/a1"
  if grep -q '^digest = sha256:f' "$work/a1/estate/platform.lock"; then sed -i 's/^digest = sha256:f/digest = sha256:e/' "$work/a1/estate/platform.lock"
  else sed -i 's/^digest = sha256:./digest = sha256:f/' "$work/a1/estate/platform.lock"; fi
  if out="$(consistent "$work/a1")"; then bad "A1 a hand-edited digest was ADMITTED"; else ok "A1 a hand-edited digest is refused: $(head -n1 <<<"$out" | sed 's/^ *//' | cut -c1-150)"; fi
  plant_copy "$work/a2"
  if grep -qx 'version = 9.9.9' "$work/a2/estate/platform.lock"; then sed -i 's/^version = .*/version = 9.9.8/' "$work/a2/estate/platform.lock"
  else sed -i 's/^version = .*/version = 9.9.9/' "$work/a2/estate/platform.lock"; fi
  if out="$(consistent "$work/a2")"; then bad "A2 a hand-edited version was ADMITTED"; else ok "A2 a hand-edited version is refused: $(head -n1 <<<"$out" | sed 's/^ *//' | cut -c1-150)"; fi
fi

# ── Part B ──
gate_require node "run the registry double"
gate_require cosign "check SEB's signature"
lib="$(dirname "${BASH_SOURCE[0]}")/lib"
node "$lib/oci-registry.mjs" "$work/port" & pid=$!
gate_on_exit "kill $pid 2>/dev/null"
for _ in $(seq 50); do [ -s "$work/port" ] && break; sleep 0.1; done
reg="$(cat "$work/port" 2>/dev/null)"; [ -n "$reg" ] || gate_abort "the registry double did not come up"
signed="$(node "$lib/oci-registry.mjs" push "$reg" seb/bundle signed)"
unsigned="$(node "$lib/oci-registry.mjs" push "$reg" seb/bundle unsigned)"
foreign="$(node "$lib/oci-registry.mjs" push "$reg" seb/bundle foreign)"
commit=0123456789abcdef0123456789abcdef01234567
( cd "$work"; COSIGN_PASSWORD=t cosign generate-key-pair --output-key-prefix seb >/dev/null 2>&1; COSIGN_PASSWORD=t cosign generate-key-pair --output-key-prefix other >/dev/null 2>&1 )
sig() { COSIGN_PASSWORD=t cosign sign --yes --tlog-upload=false --allow-insecure-registry --key "$work/$1.key" -a seb.version=1.2.3 -a seb.commit=$commit "$reg/seb/bundle@$2" >/dev/null 2>&1; }
sig seb "$signed" || gate_abort "cosign could not sign the planted bundle"
sig other "$foreign" || gate_abort "cosign could not sign the foreign bundle"
check() { # <version> <digest> <commit> → the verdict line
  ( ROOT="$root" REPO="$reg/seb/bundle" SEB_COSIGN_PUB="$work/seb.pub"
    refuse() { printf 'REFUSED: %s\n' "$*"; exit 1; }; say() { printf '%s\n' "$*"; }
    # shellcheck source=estate/lib/seb-upgrade-sign.sh
    . "$root/estate/lib/seb-upgrade-sign.sh"; signed_release "$@" )
}
case_() { # <name> <want: holds|refused> <version> <digest> <commit>
  local out rc=0; out="$(check "$3" "$4" "$5" 2>&1)" || rc=$?
  if [ "$2" = holds ]; then [ "$rc" = 0 ] && ok "$1 holds: $out" || bad "$1 was refused: $out"
  else [ "$rc" != 0 ] && grep -q '^REFUSED' <<<"$out" && ok "$1 refused: ${out#REFUSED: }" || bad "$1 was ADMITTED: $out"; fi
}
case_ B1 holds 1.2.3 "$signed" "$commit"
case_ "B2 a hand-typed (unsigned) digest" refused 1.2.3 "$unsigned" "$commit"
case_ "B3 the signed bundle named as another version" refused 1.2.4 "$signed" "$commit"
case_ "B4 the signed bundle with another tag commit" refused 1.2.3 "$signed" fedcba9876543210fedcba9876543210fedcba98
case_ "B5 a bundle signed by another key" refused 1.2.3 "$foreign" "$commit"
[ -r estate/seb-cosign.pub ] && [ "$(cat estate/seb-cosign.pub)" = "$(sed -n '/BEGIN/,/END/p' estate/seb-cosign.pub)" ] && grep -q 'BEGIN PUBLIC KEY' estate/seb-cosign.pub \
  && ok "the pinned trust anchor estate/seb-cosign.pub is a public key" || bad "estate/seb-cosign.pub is not a PEM public key"

gate_finish "$fails"
